function format(value, vars = {}) {
  return String(value).replace(/\{(\w+)\}/g, (_, key) => vars[key] ?? `{${key}}`)
}

const I18nContext = createContext({ language: 'en', setLanguage: () => {}, t: (key, vars) => format(key, vars) })

export function I18nProvider({ children }) {
  const [language, setLanguage] = useState(() => localStorage.getItem(STORAGE_KEY) || 'zh')
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, language)
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : 'en'
  }, [language])
  const value = useMemo(() => ({
    language,
    setLanguage,
    t: (key, vars) => format(language === 'zh' ? (zh[key] || key) : (en[key] || key), vars),
  }), [language])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export const useI18n = () => useContext(I18nContext)
